from __future__ import annotations

import json
import subprocess
from pathlib import Path
from xml.etree import ElementTree

import pandas as pd

from mdrd.common import now, read_json, sha256, write_json


def _read(path):
    return read_json(path) if Path(path).exists() else None


def _markdown(path, text):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text.rstrip() + "\n", encoding="utf-8")


def _table(rows, columns):
    def value(item):
        return "N/A" if item is None else str(item).replace("|", "/").replace("\n", " ")
    return "| " + " | ".join(columns) + " |\n| " + " | ".join("---" for _ in columns) + " |\n" + "\n".join("| " + " | ".join(value(row.get(name)) for name in columns) + " |" for row in rows)


def acceptance_status(engineering_checks, research_checks):
    if engineering_checks.get("test_failure") or engineering_checks.get("phase01_modified"):
        engineering = "FAIL"
    elif not engineering_checks.get("data_available"):
        engineering = "BLOCKED"
    elif all(value for key, value in engineering_checks.items() if key not in {"phase01_modified", "test_failure"}):
        engineering = "PASS"
    else:
        engineering = "PARTIAL"
    verified = [bool(value) for value in research_checks.values()]
    research = "READY" if verified and all(verified) else "PARTIAL" if verified and sum(verified) >= 3 and research_checks.get("plant_masks_verified") else "INSUFFICIENT"
    return engineering, research


